#!/usr/bin/env python3
"""Author the factory preset banks for the 1.8 instrument shelf as data and emit Source/SignaturePresets18.inl.

Names carry their category as "Category | Name" (the preset menu groups on it).
Every preset starts from the plug-in defaults (applyPreset resets the bank first), so only the parameters that
matter are listed. mods: (source, destination, depth) fill the 8-slot matrix; sources use SqSynth::ModSource
numbering (1 env1 2 env2 3 env3 4 lfo1 5 lfo2 6 velocity 7 key 8 modWheel 9 aftertouch 10 modX 11 modY
12..15 macro1..4 16 random)."""
import os, sys

OUT = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'Source', 'SignaturePresets18.inl')

SINE, TRI, SAW, SQR, PULSE, NOISE = 0, 1, 2, 3, 4, 5
LP24, LP12, HP24, HP12, BP, NOTCH, LADDER = 0, 1, 2, 3, 4, 5, 6
POLY, MONO, LEGATO = 0, 1, 2
ENV1, ENV2, ENV3, LFO1, LFO2, VEL, KEY, WHEEL, AT, MODX, MODY, M1, M2, M3, M4, RND = range(1, 17)

banks = {}
def preset(bank, cat, name, adv=False, props=None, mods=None, **vals):
    banks.setdefault(bank, []).append((cat, name, adv, vals, props or {}, mods or []))

