# ------------------------------------------------------------------------------------------------ measured level trims
# scripts/preset_levels_18.json holds per-preset level offsets measured by the preset sweep (target peak -6 dBFS on a
# C3 note + C4 chord at velocity 100-110), so every preset lands at a usable level out of the box.
import json
_lv = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'preset_levels_18.json')
if os.path.exists(_lv):
    trims = json.load(open(_lv))
    for bank, items in banks.items():
        for n, (cat, name, adv, vals, props, mods) in enumerate(items):
            key = f'{bank}|{cat} | {name}'
            if key in trims:
                default = -3 if bank == 'Thump' else -6
                lo, hi = (-24, 6)
                vals['level'] = round(max(lo, min(hi, vals.get('level', default) + trims[key])), 1)

# ------------------------------------------------------------------------------------------------ emit
def cpp(v):
    if isinstance(v, bool): return '1' if v else '0'
    if isinstance(v, int): return str(v)
    s = repr(float(v))
    return s + 'f'

lines = ['// Generated by scripts/gen_presets_18.py - factory presets for the 1.8 instrument shelf. Do not edit by hand.',
         '// Included inside SignaturePresets::bank() (SignaturePresets.h).']
b2 = ['// Generated by scripts/gen_presets_18.py - the Blossom 2 additions, spliced into the hand-written bank. Do not edit by hand.']
for cat, name, adv, vals, props, mods in banks.pop('Blossom 2', []):
    pv = ', '.join(f'N ("{k}", {cpp(v)})' for k, v in vals.items())
    pr = ', '.join(f'{{ "{k}", {cpp(v)} }}' for k, v in props.items())
    b2.append(f'            {"A" if adv else "B"} ("{cat} | {name}", {{ {pv} }}, {{ {pr} }}),')
b2[-1] = b2[-1].rstrip(',')
open(os.path.join(os.path.dirname(OUT), 'SignaturePresetsBlossom2.inl'), 'w').write('\n'.join(b2) + '\n')
for bank, items in banks.items():
    lines.append(f'        {{ "{bank}", {{')
    for cat, name, adv, vals, props, mods in items:
        pv = ', '.join(f'N ("{k}", {cpp(v)})' for k, v in vals.items())
        pr = ', '.join(f'{{ "{k}", {cpp(v)} }}' for k, v in props.items())
        md = ', '.join(f'{{ {s}, "{d}", {cpp(dep)} }}' for s, d, dep in mods)
        fn = 'A' if adv else 'B'
        lines.append(f'            {fn} ("{cat} | {name}", {{ {pv} }}, {{ {pr} }}, {{ {md} }}),')
    lines[-1] = lines[-1].rstrip(',')
    lines.append('        } },')
open(OUT, 'w').write('\n'.join(lines) + '\n')
for bank, items in banks.items(): print(f'{bank}: {len(items)} presets, {len(set(c for c, *_ in items))} categories')
print('wrote', OUT)
